package net.officefloor.hq.app.claim;

import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * How a claim's live figures (the rate step and the late charge) round to cents: half up when the
 * claim is dated before the sheet's policy date (none: the sheet's today), else half to even. A
 * correction rounds by the date of the claim it corrects, not its own.
 */
public final class Rounding {

    private Rounding() {}

    /** The date a claim rounds by: a correction's corrected claim's date (from {@code datesByNumber}), else its own. */
    public static LocalDate basisOf(Claim claim, Map<String, LocalDate> datesByNumber) {
        if (claim.getCorrects() != null) {
            LocalDate corrected = datesByNumber.get(claim.getCorrects());
            if (corrected != null) return corrected;
        }
        return claim.getDate();
    }

    /** The rounding of a claim rounding by the given date. */
    public static RoundingMode of(LocalDate basis, LocalDate policyDate, LocalDate today) {
        LocalDate policy = policyDate != null ? policyDate : today;
        return policy != null && basis.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** The dates of the numbered claims, by number. */
    public static Map<String, LocalDate> datesByNumber(List<Claim> claims) {
        Map<String, LocalDate> dates = new HashMap<>();
        for (Claim c : claims) {
            if (c.getNumber() != null) dates.put(c.getNumber(), c.getDate());
        }
        return dates;
    }
}
package net.officefloor.hq.app.rate;


/**
 * The sheet's rates for each grade, each from a date (or from the beginning of time): set one grade
 * and from-date at a time, replacing any rate it had. A date's rate is the one with the latest
 * from-date on or before it.
 */
@Service
public class RateService {

    private final RateRepository rates;
    private final SheetRepository sheets;
    private final RollupService rollup;
    private final Audit audit;

    public RateService(RateRepository rates, SheetRepository sheets, RollupService rollup, Audit audit) {
        this.rates = rates;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdOrderByGradeAscFromDateAsc(sheetId);
    }

    /** The grade's rate on the date: the one with the latest from-date on or before it, if any and not ended. */
    @Transactional(readOnly = true)
    public Optional<Rate> on(String sheetId, String grade, LocalDate date) {
        return Rate.inForce(rates.findBySheetIdAndGrade(sheetId, grade), date);
    }

    @Transactional
    public Rate set(String sheetId, String user, String grade, LocalDate from, LocalDate to, BigDecimal pct) {
        if (to != null && from != null && to.isBefore(from)) throw new RateDatesException();
        // Lock the sheet so two users setting the same grade and from-date at once replace one rate.
        sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Optional<Rate> existing = from == null
                ? rates.findBySheetIdAndGradeAndFromDateIsNull(sheetId, grade)
                : rates.findBySheetIdAndGradeAndFromDate(sheetId, grade, from);
        Rate rate = existing.orElseGet(() -> new Rate(sheetId, grade, from, to, pct));
        rate.setPct(pct);
        rate.setToDate(to);
        Rate saved = rates.saveAndFlush(rate);
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user.strip()
                + " grade=" + saved.getGrade() + " rate=" + saved.getPct().setScale(2).toPlainString()
                + (saved.getFromDate() != null ? " from=" + saved.getFromDate() : "")
                + (saved.getToDate() != null ? " to=" + saved.getToDate() : ""));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }
}
package net.officefloor.hq.app.rate;


/**
 * The sheet's rate for one grade from a date: a percent with two decimals (0.00 or more). A rate
 * with no from-date applies from the beginning of time; one with a to-date applies through it.
 */
@Entity
@Table(name = "rate")
public class Rate {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "grade", nullable = false)
    private String grade;

    @Column(name = "pct", nullable = false, precision = 7, scale = 2)
    private BigDecimal pct;

    @Column(name = "from_date")
    private LocalDate fromDate;

    @Column(name = "to_date")
    private LocalDate toDate;

    protected Rate() {}

    public Rate(String sheetId, String grade, LocalDate fromDate, LocalDate toDate, BigDecimal pct) {
        this.sheetId = sheetId;
        this.grade = grade;
        this.fromDate = fromDate;
        this.toDate = toDate;
        this.pct = pct;
    }

    /**
     * Of one grade's rates, the one in force on the date: the one with the latest from-date on or
     * before it, unless the date is after that rate's to-date (then none).
     */
    public static Optional<Rate> inForce(Collection<Rate> rates, LocalDate date) {
        return rates.stream()
                .filter(rate -> rate.appliesOn(date))
                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .filter(rate -> rate.toDate == null || !date.isAfter(rate.toDate));
    }

    public Long getId() { return id; }

    public String getSheetId() { return sheetId; }

    public String getGrade() { return grade; }

    /** The first date it applies on; null when it applies from the beginning of time. */
    public LocalDate getFromDate() { return fromDate; }

    /** Whether it applies on the date: it has no from-date, or one on or before the date. */
    public boolean appliesOn(LocalDate date) { return fromDate == null || !fromDate.isAfter(date); }

    /** The last date it applies on; null when it has no end. */
    public LocalDate getToDate() { return toDate; }

    public void setToDate(LocalDate toDate) { this.toDate = toDate; }

    public BigDecimal getPct() { return pct; }

    public void setPct(BigDecimal pct) { this.pct = pct; }
}

