        LocalDate dueBy = on.plusDays(person.getTerms() != null ? person.getTerms()
                : settings.termsFor(sheetId, person.gradeOn(on), on));
        Claim split = new Claim(sheetId, person.getId(), amount, on, original.getNote(), dueBy);
