-- Each claim's status log, oldest first: one line per status it has had (DRAFT when added), who
-- gave it, the sheet's today then and the claim's due as it was computed at that moment (empty
-- when it had none). Claims added before the log was kept start with no lines.
CREATE TABLE claim_log (
    claim_id  BIGINT       NOT NULL REFERENCES claim (id),
    seq       INT          NOT NULL,
    status    VARCHAR(20)  NOT NULL,
    by_user   VARCHAR(100) NOT NULL,
    log_date  DATE         NOT NULL,
    due       DECIMAL(14, 2),
    PRIMARY KEY (claim_id, seq)
);
-- A person may have several holds over time, each from a from-date to an optional to-date (null:
-- open-ended). Only their open claims dated within a hold, and not bound by a statement, are left
-- out of the live totals. A person held before holds had dates is held from the beginning of time
-- (a null from-date).
CREATE TABLE person_hold (
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE,
    to_date   DATE
);
CREATE INDEX person_hold_person ON person_hold (person_id);
INSERT INTO person_hold (person_id, from_date, to_date) SELECT id, NULL, NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
-- Terms can be set per grade: a grade with a row here uses its terms, any other the sheet's terms.
CREATE TABLE sheet_grade_terms (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade    CHAR(1)      NOT NULL,
    terms    INT          NOT NULL,
    PRIMARY KEY (sheet_id, grade)
);

-- A claim's due-by is fixed when it is added. Existing claims keep the due-by they show: their
-- date plus their sheet's terms.
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim SET due_by = DATEADD(DAY, (SELECT s.terms FROM sheet s WHERE s.id = claim.sheet_id), claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
-- The sheet's rate for each grade: a percent with two decimals (0.00 or more). A grade with no row
-- has no rate, and its claims' due is n/a.
CREATE TABLE rate (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade    CHAR(1)      NOT NULL,
    pct      DECIMAL(7, 2) NOT NULL CHECK (pct >= 0)
);
CREATE UNIQUE INDEX rate_sheet_grade ON rate (sheet_id, grade);
-- A rate may carry a from-date: a grade may have several rates, and a claim takes the one whose
-- from-date is the latest on or before its date. A rate with no from-date applies from the
-- beginning of time. One rate per grade and from-date (the service keeps the no-from-date one
-- unique, since NULLs are distinct in a unique index).
ALTER TABLE rate ADD COLUMN from_date DATE;
DROP INDEX rate_sheet_grade;
CREATE UNIQUE INDEX rate_sheet_grade_from ON rate (sheet_id, grade, from_date);
-- A person's grade is dated: person.grade is the first grade they were given, in force from the
-- beginning of time; each later grade recorded is a row here, in force from its from-date until the
-- next one. One grade per person and from-date.
CREATE TABLE person_grade (
    person_id BIGINT  NOT NULL REFERENCES person (id),
    from_date DATE    NOT NULL,
    grade     CHAR(1) NOT NULL,
    PRIMARY KEY (person_id, from_date)
);

